local SwordsmithMaker = {}
local PRODUCTS = {
    iron_sword = { name = "Železen meč", ironCost = 2, time = 2, cost = 40, attack = 8, durability = 20, description = "Preprost železen meč za pehoto." },
    steel_long_sword = { name = "Jeklen dolg meč", steelCost = 2, ironCost = 1, time = 4, cost = 120, attack = 14, durability = 30, prestige = 2, description = "Jeklen dolg meč za viteze." },
    silver_hilt_sword = { name = "Srebrnjak ročajski meč", steelCost = 2, silverCost = 1, time = 6, cost = 280, attack = 18, durability = 35, prestige = 5, happiness = 1, description = "Meč s srebrnim ročajem." },
    damascus_sword = { name = "Damascenski meč", steelCost = 3, silverCost = 1, time = 8, cost = 600, attack = 24, durability = 45, prestige = 10, happiness = 2, description = "Damascenski meč z močnim rezom." },
    jewel_pommel_sword = { name = "Draguljni meč z drobnim gumbom", steelCost = 3, goldCost = 1, jewelCost = 1, time = 11, cost = 1300, attack = 30, durability = 55, prestige = 18, happiness = 4, description = "Meč z zlatim okovjem in draguljem." },
    royal_ceremonial_sword = { name = "Kraljevski slovesni meč", steelCost = 4, goldCost = 3, silverCost = 2, jewelCost = 3, pearlCost = 1, time = 16, cost = 3200, attack = 45, durability = 80, prestige = 65, happiness = 13, description = "Veliki kraljevski slovesni meč z zlatim, draguljnim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Mečarska delavnica", cost = { gold = 320, wood = 120, stone = 100 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Mečarska kovačija", cost = { gold = 1000, wood = 220, stone = 250, iron = 10 }, upkeep = 25, qualityBonus = 18 },
    tempering_room = { name = "Žarilnica", cost = { gold = 2200, wood = 300, stone = 500, silver = 30, steel = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_sword_atelier = { name = "Kraljevski atelje mečev", cost = { gold = 9000, wood = 600, stone = 900, gold = 100, jewel = 25 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
SwordsmithMaker.ironStock = 16; SwordsmithMaker.steelStock = 14; SwordsmithMaker.silverStock = 8; SwordsmithMaker.goldStock = 6; SwordsmithMaker.jewelStock = 6; SwordsmithMaker.pearlStock = 4
SwordsmithMaker.productStock = {}; SwordsmithMaker.buildings = {}; SwordsmithMaker.maker = nil; SwordsmithMaker.activeMaking = {}; SwordsmithMaker.totalProducts = 0; SwordsmithMaker.dayTimer = 0
function SwordsmithMaker.init() SwordsmithMaker.ironStock=16; SwordsmithMaker.steelStock=14; SwordsmithMaker.silverStock=8; SwordsmithMaker.goldStock=6; SwordsmithMaker.jewelStock=6; SwordsmithMaker.pearlStock=4; SwordsmithMaker.productStock={}; SwordsmithMaker.buildings={}; SwordsmithMaker.maker=nil; SwordsmithMaker.activeMaking={}; SwordsmithMaker.totalProducts=0; SwordsmithMaker.dayTimer=0; print("[SwordsmithMaker] Royal Swordsmith Maker System initialized (6 products, 4 buildings)") end
function SwordsmithMaker.hireMaker(n,s) s=s or math.random(55,95); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SwordsmithMaker.maker={name=n or ("Mečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mečar najet: %s (spretnost: %d)",SwordsmithMaker.maker.name,s),"success") end; return true end
function SwordsmithMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SwordsmithMaker.build(id) local ok,e=SwordsmithMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SwordsmithMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SwordsmithMaker.getQualityBonus() local b=0; for _,bd in ipairs(SwordsmithMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SwordsmithMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SwordsmithMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and SwordsmithMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and SwordsmithMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SwordsmithMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SwordsmithMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SwordsmithMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SwordsmithMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SwordsmithMaker.maker then return false,"Potreben mečar" end; return true end
function SwordsmithMaker.make(pt,qty) qty=qty or 1; local ok,e=SwordsmithMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SwordsmithMaker.ironStock=SwordsmithMaker.ironStock-d.ironCost*qty end; if d.steelCost then SwordsmithMaker.steelStock=SwordsmithMaker.steelStock-d.steelCost*qty end; if d.silverCost then SwordsmithMaker.silverStock=SwordsmithMaker.silverStock-d.silverCost*qty end; if d.goldCost then SwordsmithMaker.goldStock=SwordsmithMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SwordsmithMaker.jewelStock=SwordsmithMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SwordsmithMaker.pearlStock=SwordsmithMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SwordsmithMaker.maker then t=math.max(1,t-math.floor(SwordsmithMaker.maker.skill/12)) end; table.insert(SwordsmithMaker.activeMaking,{id="sword_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SwordsmithMaker.completeMaking(m) local q=1.0+(SwordsmithMaker.getQualityBonus()/100); if SwordsmithMaker.maker then q=q+(SwordsmithMaker.maker.skill/150) end; q=math.min(2.5,q); SwordsmithMaker.productStock[m.productType]=(SwordsmithMaker.productStock[m.productType] or 0)+m.quantity; SwordsmithMaker.totalProducts=SwordsmithMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SwordsmithMaker.maker then SwordsmithMaker.maker.itemsMade=SwordsmithMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SwordsmithMaker.maker.skill=math.min(100,SwordsmithMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Meč izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sword.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function SwordsmithMaker.update(dt) if not _G.state then return end; SwordsmithMaker.dayTimer=SwordsmithMaker.dayTimer+dt; if SwordsmithMaker.dayTimer>=30 then SwordsmithMaker.dayTimer=0; for i=#SwordsmithMaker.activeMaking,1,-1 do local m=SwordsmithMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SwordsmithMaker.completeMaking(m); table.remove(SwordsmithMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SwordsmithMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SwordsmithMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SwordsmithMaker.getStats() return {ironStock=SwordsmithMaker.ironStock,steelStock=SwordsmithMaker.steelStock,silverStock=SwordsmithMaker.silverStock,goldStock=SwordsmithMaker.goldStock,jewelStock=SwordsmithMaker.jewelStock,pearlStock=SwordsmithMaker.pearlStock,productStock=SwordsmithMaker.productStock,numBuildings=#SwordsmithMaker.buildings,hasMaker=SwordsmithMaker.maker~=nil,makerName=SwordsmithMaker.maker and SwordsmithMaker.maker.name or "—",makerSkill=SwordsmithMaker.maker and SwordsmithMaker.maker.skill or 0,activeMaking=#SwordsmithMaker.activeMaking,totalProducts=SwordsmithMaker.totalProducts} end
return SwordsmithMaker
